#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    // Part 1: Fig. 4.5 - Summation with for
    unsigned int sum = 0;
    for (unsigned int number = 2; number <= 100; number += 2) {
        sum += number;
    }
    std::cout << "Sum is " << sum << "\n\n";

    // Part 2: Fig. 4.6 - Calculating compound interest
    double principal = 1000.0;
    double rate = 0.05;

    // Output table column heads
    std::cout << std::setw(4) << "Year" 
              << std::setw(21) << "Amount on deposit" << "\n";

    // Calculate amount on deposit for each of ten years
    for (unsigned int year = 1; year <= 10; ++year) {
        double amount = principal * std::pow(1.0 + rate, year);
        std::cout << std::setw(4) << year 
                  << std::setw(21) << std::fixed << std::setprecision(2) 
                  << amount << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    unsigned int aCount = 0;
    unsigned int bCount = 0;
    unsigned int cCount = 0;
    unsigned int dCount = 0;
    unsigned int fCount = 0;

    int grade;
    // Read characters until EOF or stream termination
    while ((grade = std::cin.get()) != EOF) {
        switch (grade) {
            case 'A': // grade was uppercase A
            case 'a': // or lowercase a
                ++aCount;
                break; // necessary to exit switch

            case 'B': // grade was uppercase B
            case 'b': // or lowercase b
                ++bCount;
                break;

            case 'C': // grade was uppercase C
            case 'c': // or lowercase c
                ++cCount;
                break;

            case 'D': // grade was uppercase D
            case 'd': // or lowercase d
                ++dCount;
                break;

            case 'F': // grade was uppercase F
            case 'f': // or lowercase f
                ++fCount;
                break;

            case '\n': // ignore newlines,
            case '\t': // tabs,
            case ' ':  // and spaces in input
                break;
        }
    }

    std::cout << "A: " << aCount << "\n"
              << "B: " << bCount << "\n"
              << "C: " << cCount << "\n"
              << "D: " << dCount << "\n"
              << "F: " << fCount << "\n";

    return 0;
}
